-- Azure SQL migration 0003: the app's database user and its least-privilege role (document 22, section 11.1).
-- Generated by SqlServerSchemaScript.GenerateAppUser from the logical model's delete policies.
-- Do not edit by hand: run the local server's schema-script command, or the store tests with PRODUCT_WRITE_SQL=1.
--
-- Variable $(AppIdentityName): the name of the app's user-assigned managed identity, as Microsoft Entra ID shows it.
-- Empty skips the user (a test server without Microsoft Entra ID). Run by the deployment identity, which is the database
-- owner; another deployment identity is added to product_migrator (and given its DDL rights) by a person.
--
-- product_app: reads and writes the engine's rows and nothing else. No DDL. No delete in config or audit, and none on the
-- operational tables whose rows are never deleted (document 22, section 2.5); the engine decides which drafts go.
-- No read of history tables or ledger views: the engine reads current rows only, and auditors read history elsewhere.
-- The approval outcome columns are written only in the approval runner's request or in a person's own answer request
-- (0002, D-38). The separate approval_writer principal of document 22 needs a second identity and connection and is
-- not in this release.

IF DATABASE_PRINCIPAL_ID(N'product_app') IS NULL CREATE ROLE [product_app];
IF DATABASE_PRINCIPAL_ID(N'product_migrator') IS NULL CREATE ROLE [product_migrator];
GO

GRANT SELECT, INSERT, UPDATE ON SCHEMA::[config] TO [product_app];
GRANT SELECT, INSERT, UPDATE, DELETE ON SCHEMA::[ops] TO [product_app];
GRANT SELECT, INSERT ON SCHEMA::[audit] TO [product_app];
DENY DELETE ON [ops].[PrincipalReference] TO [product_app];
DENY DELETE ON [ops].[Decision] TO [product_app];
DENY DELETE ON [ops].[ApprovalRecord] TO [product_app];
DENY DELETE ON [ops].[DeploymentRecord] TO [product_app];
DENY DELETE ON [ops].[EvidenceLink] TO [product_app];
DENY ALTER ON SCHEMA::[config] TO [product_app];
DENY ALTER ON SCHEMA::[ops] TO [product_app];
DENY ALTER ON SCHEMA::[audit] TO [product_app];
DENY ALTER ON SCHEMA::[security] TO [product_app];
DENY ALTER ON SCHEMA::[host] TO [product_app];
GO

DECLARE @deny nvarchar(max);
SELECT @deny = STRING_AGG(CAST(N'DENY SELECT ON ' + QUOTENAME(s.[name]) + N'.' + QUOTENAME(o.[name]) + N' TO [product_app];' AS nvarchar(max)), NCHAR(10))
FROM
(
    SELECT h.[schema_id], h.[name] FROM sys.tables AS t JOIN sys.tables AS h ON h.[object_id] = t.[history_table_id]
    WHERE SCHEMA_NAME(t.[schema_id]) IN (N'config', N'ops', N'audit')
    UNION ALL
    SELECT v.[schema_id], v.[name] FROM sys.tables AS t JOIN sys.views AS v ON v.[object_id] = t.[ledger_view_id]
    WHERE SCHEMA_NAME(t.[schema_id]) IN (N'config', N'ops', N'audit')
) AS o
JOIN sys.schemas AS s ON s.[schema_id] = o.[schema_id];
IF @deny IS NOT NULL EXEC sys.sp_executesql @deny;
GO

IF N'$(AppIdentityName)' <> N'' AND DATABASE_PRINCIPAL_ID(N'$(AppIdentityName)') IS NULL
    EXEC (N'CREATE USER [$(AppIdentityName)] FROM EXTERNAL PROVIDER');
IF N'$(AppIdentityName)' <> N'' AND NOT EXISTS (
    SELECT 1 FROM sys.database_role_members AS m
    WHERE m.[role_principal_id] = DATABASE_PRINCIPAL_ID(N'product_app') AND m.[member_principal_id] = DATABASE_PRINCIPAL_ID(N'$(AppIdentityName)'))
    EXEC (N'ALTER ROLE [product_app] ADD MEMBER [$(AppIdentityName)]');
GO
